/**
 * Export and recovery (spec sections 49, 52).
 * Downloads are generated by the local server - nothing leaves the machine.
 */

import { useState } from 'react';
import { useStore } from '../lib/store.js';

export function ExportPanel({ token }: { token: string }) {
  const pushToast = useStore((s) => s.pushToast);
  const leaderboard = useStore((s) => s.leaderboard);
  const config = useStore((s) => s.config);
  const [busy, setBusy] = useState(false);
  const [lastBackup, setLastBackup] = useState<string | null>(null);

  async function download(path: string, filename: string) {
    setBusy(true);
    try {
      const response = await fetch(path, { headers: { authorization: `Bearer ${token}` } });
      if (!response.ok) throw new Error('Export failed');
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = filename;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);
      pushToast({ kind: 'gain', title: `Downloaded ${filename}` });
    } catch (error) {
      pushToast({ kind: 'warn', title: error instanceof Error ? error.message : 'Export failed' });
    } finally {
      setBusy(false);
    }
  }

  async function backup() {
    setBusy(true);
    try {
      const response = await fetch('/api/organizer/backup', {
        method: 'POST',
        headers: { authorization: `Bearer ${token}` },
      });
      const payload = (await response.json()) as { file?: string; message?: string };
      if (!response.ok) throw new Error(payload.message ?? 'Backup failed');
      setLastBackup(payload.file ?? null);
      pushToast({ kind: 'gain', title: 'Database backed up', detail: payload.file });
    } catch (error) {
      pushToast({ kind: 'warn', title: error instanceof Error ? error.message : 'Backup failed' });
    } finally {
      setBusy(false);
    }
  }

  const onPodium = leaderboard.filter((r) => r.podium !== null).length;

  return (
    <section className="panel panel--flush">
      <div className="panel__head">
        <span className="panel__title">Results &amp; recovery</span>
        <span className="badge badge--premium">
          {onPodium}/{config.podiumPlaces} on the podium
        </span>
      </div>

      <div className="panel__body stack">
        <button
          className="btn btn--primary btn--block"
          onClick={() => download('/api/export/results.csv', 'code-market-results.csv')}
          disabled={busy}
        >
          Download results (CSV)
        </button>
        <button
          className="btn btn--block"
          onClick={() => download('/api/export/results.json', 'code-market-results.json')}
          disabled={busy}
        >
          Download full archive (JSON)
        </button>
        <button
          className="btn btn--block"
          onClick={() => download('/api/export/audit.txt', 'code-market-audit.txt')}
          disabled={busy}
        >
          Download audit trail (TXT)
        </button>

        <hr className="divider" />

        <button className="btn btn--block" onClick={backup} disabled={busy}>
          Back up the database now
        </button>
        {lastBackup ? (
          <p className="dim" style={{ fontSize: 'var(--fs-2xs)', wordBreak: 'break-all' }}>
            Last backup: {lastBackup}
          </p>
        ) : null}

        <p className="dim" style={{ fontSize: 'var(--fs-xs)' }}>
          The server can be restarted at any time — teams reconnect automatically and the round
          resumes exactly where it was.
        </p>
      </div>
    </section>
  );
}
